using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Interop;

namespace QiDesk {
public static class ProjectPluginTests {
    public static void Run(string root,Action<bool,string> check){
        string folder=Path.Combine(root,"project-ignore");Directory.CreateDirectory(folder);string src=Path.Combine(folder,"src");Directory.CreateDirectory(src);string cache=Path.Combine(folder,"cache");Directory.CreateDirectory(cache);string log=Path.Combine(src,"build.log"),keep=Path.Combine(src,"keep.log"),child=Path.Combine(cache,"keep.txt");File.WriteAllText(log,"log");File.WriteAllText(keep,"keep");File.WriteAllText(child,"cache");string file=Path.Combine(folder,".gitignore");File.WriteAllText(file,"# comment\n*.log\n!keep.log\ncache/\n!cache/keep.txt\n/root-only.txt\n");var set=IgnoreFiles.Read(file,"",folder,false);check(set.Lines.Count==5&&!set.Lines.Any(x=>x.StartsWith("#")),"ignore file import removes comments and preserves rule order");check(IgnoreFiles.Matches(set,log)&&!IgnoreFiles.Matches(set,keep),"ignore file negation restores matching files within an allowed parent");check(IgnoreFiles.Matches(set,child),"git ignore semantics keep child excluded when parent directory is excluded");check(IgnoreFiles.Matches(set,Path.Combine(folder,"root-only.txt"))&&!IgnoreFiles.Matches(set,Path.Combine(src,"root-only.txt")),"leading slash anchors ignore pattern to imported root");
        var glob=new IgnoreFileSet(){Root=folder,Lines=IgnoreFiles.Parse("docs/**/draft?.[mp][dn]\n\\#secret\n\\!literal\n")};check(IgnoreFiles.Matches(glob,Path.Combine(folder,"docs","draft1.md"))&&IgnoreFiles.Matches(glob,Path.Combine(folder,"docs","nested","draft2.pn")),"double star and character ranges match zero or multiple path segments");check(IgnoreFiles.Matches(glob,Path.Combine(src,"#secret"))&&IgnoreFiles.Matches(glob,Path.Combine(src,"!literal")),"escaped leading hash and exclamation remain literal filenames");check(!IgnoreFiles.Matches(set,Path.Combine(folder+"-other","x.log")),"imported global ignore rules do not escape their project root");
        var state=new State();var a=new Group(){Name="A"};var b=new Group(){Name="B"};state.Groups.AddRange(new[]{a,b});set.ScopeId=a.Id;IgnoreFiles.Import(state,set);check(IgnoreFiles.Ignored(state,log,a)&&!IgnoreFiles.Ignored(state,log,b),"imported ignore file can be local to a single partition");set.Enabled=false;check(!IgnoreFiles.Ignored(state,log,a),"disabling an imported source restores visible files");set.Enabled=true;var replacement=IgnoreFiles.Read(file,a.Id,folder,false);IgnoreFiles.Import(state,replacement);check(state.IgnoreFiles.Count==1&&state.IgnoreFiles[0].Id==set.Id,"reimport updates source in place without duplicating rule books");
        var store=new Store(Path.Combine(root,"project-persistence"));store.Checkpoint();IgnoreFiles.Import(store.Data,IgnoreFiles.Read(file,"",folder,false));store.Save();var loaded=new Store(store.Root);check(loaded.Data.IgnoreFiles.Count==1&&loaded.Ignored(log,null),"imported ignore source and root semantics persist on restart");check(store.Undo()&&store.Data.IgnoreFiles.Count==0,"imported rule book supports undo");
        File.WriteAllText(Path.Combine(folder,".cursorignore"),"private/**\n");WorkspaceConnections.Connect(store.Data,folder,"test MCP",false);check(store.Data.WorkFolders.Contains(folder)&&store.Data.IgnoreFiles.Count==2&&store.Data.WorkSources[folder]=="test MCP","workspace connection automatically associates Git and Cursor ignore files");File.AppendAllText(file,"new-artifact.*\n");check(IgnoreFiles.Sync(store.Data)&&store.Ignored(Path.Combine(folder,"new-artifact.txt"),null),"project ignore source modifications refresh associated rules");store.Data.AutoImportIgnoreFiles=false;check(!store.Ignored(log,null),"automatic ignore-file association can be disabled independently");store.Data.AutoImportIgnoreFiles=true;store.Data.AutoDetectWorkspaces=false;string other=Path.Combine(root,"second-project");Directory.CreateDirectory(other);check(!WorkspaceConnections.Connect(store.Data,other,"roots",true)&&!store.Data.WorkFolders.Contains(other),"MCP roots respect the automatic project detection opt-out");bool rejected=false;try{WorkspaceConnections.Connect(store.Data,Path.GetPathRoot(folder),"roots",false);}catch{rejected=true;}check(rejected,"automatic workspace registration rejects whole-drive roots");check(WorkspaceConnections.RootFromUri(new Uri(folder).AbsoluteUri)==folder,"MCP file URI resolves to the local project directory");
        string pluginFile=Path.Combine(folder,"focus.qidesk-plugin.json");File.WriteAllText(pluginFile,"{\"id\":\"focus\",\"name\":\"Focus\",\"kind\":\"note\",\"text\":\"Work on one thing\"}");WidgetPlugins.Import(store.Data,WidgetPlugins.Read(pluginFile));var widget=WidgetPlugins.Create(store.Data,"focus",new[]{new Rect(0,0,1920,1040)});check(widget.Text=="Work on one thing"&&store.Data.Widgets.Count==1,"declarative plugin import creates the expected desktop component");store.Save();var again=new Store(store.Root);check(again.Data.Plugins.Count==1&&again.Data.Widgets[0].PluginId=="focus","plugins and desktop widget placement persist on restart");File.WriteAllText(pluginFile,"{\"id\":\"bad\",\"name\":\"Bad\",\"kind\":\"note\",\"command\":\"do something\"}");rejected=false;try{WidgetPlugins.Read(pluginFile);}catch{rejected=true;}check(rejected,"plugin manifest rejects executable command fields");
        var days=WidgetPlugins.Days(new DateTime(2024,2,1));check(days.Length==42&&days[0].DayOfWeek==DayOfWeek.Monday&&days.Count(d=>d.Year==2024&&d.Month==2)==29,"calendar grid starts Monday and handles leap-year February");check(WidgetPlugins.Days(new DateTime(2026,10,1),true)[0].DayOfWeek==DayOfWeek.Sunday,"calendar week can start on Sunday");var spring=LunarCalendar.FromSolar(new DateTime(2024,2,10));var mid=LunarCalendar.FromSolar(new DateTime(2026,9,25));check(spring!=null&&spring.Month==1&&spring.Day==1&&!spring.Leap&&mid!=null&&mid.Month==8&&mid.Day==15,"lunar calendar maps spring festival and mid-autumn to the correct lunar dates");var horse=LunarCalendar.FromSolar(new DateTime(2026,10,16));check(horse!=null&&horse.Zodiac=="马"&&horse.GanZhi=="丙午"&&LunarCalendar.Term(new DateTime(2026,12,22))=="冬至"&&LunarCalendar.Term(new DateTime(2026,4,5))=="清明","lunar calendar reports the zodiac year, ganzhi and solar terms");check(LunarCalendar.CellLabel(new DateTime(2026,2,17),LunarCalendar.FromSolar(new DateTime(2026,2,17)))=="春节"&&LunarCalendar.CellLabel(new DateTime(2026,9,25),LunarCalendar.FromSolar(new DateTime(2026,9,25)))=="中秋节"&&LunarCalendar.FromSolar(new DateTime(1899,1,1))==null,"calendar cell labels prefer festivals and out-of-range dates fall back safely");var clock=new DesktopWidget(){TimeZone="UTC"};check(WidgetPlugins.Time(clock,new DateTimeOffset(2026,10,13,10,20,30,TimeSpan.FromHours(8))).Hour==2,"clock component converts the chosen time zone");widget.X=111;widget.Y=222;store.RecordLayout("widget-profile");widget.X=444;check(store.RestoreLayout("widget-profile")&&widget.X==111&&widget.Y==222,"desktop widget geometry participates in layout profiles");
        var c=new Controller(store);var connect=new Dictionary<string,object>{{"name","qidesk_connect_workspace"},{"arguments",new Dictionary<string,object>{{"path",other},{"source","test"}}}};McpBridge.Execute(c,connect);check(store.Data.WorkFolders.Contains(other),"explicit MCP connect tool registers a project even when automatic detection is disabled");
        store.Data.AutoDetectWorkspaces=true;store.Data.WorkFolders.Remove(other);store.Data.IgnoredWorkFolders.Add(other);check(!WorkspaceConnections.Connect(store.Data,other,"roots",true)&&!store.Data.WorkFolders.Contains(other),"project opt-out prevents subsequent MCP roots from silently readding it");WorkspaceConnections.Connect(store.Data,other,"manual restore",false);check(store.Data.WorkFolders.Contains(other)&&!store.Data.IgnoredWorkFolders.Contains(other),"explicitly reconnecting project clears its individual opt-out");
        string privateRoot=Path.Combine(folder,"private");Directory.CreateDirectory(privateRoot);File.WriteAllText(Path.Combine(privateRoot,"ChatGPT-result.txt"),"private");check(WorkDetection.Scan(store.Data).All(candidate=>!candidate.Path.StartsWith(privateRoot,StringComparison.OrdinalIgnoreCase)),"workspace candidate detection respects imported Cursor ignores before returning filenames");
    }
    public static void Native(string root,Controller controller,Window owner,Action<bool,string> check){var clock=new DesktopWidget(){Name="Clock fixture",PluginId="clock",X=40,Y=60};var w=new WidgetWindow(controller,clock);try{w.Show();w.UpdateLayout();check(Texts(w).Any(t=>t.Text.Contains(":")),"visible clock plugin renders a current time value");check(w.PlaceOnDesktop(Shell.DesktopHost())&&Shell.DesktopBindingValid(w,Shell.DesktopHost()),"widget window retains transparent top-level desktop ownership");Shell.BeginInlineInput(w);check((Shell.ExtendedStyle(w)&0x08000000L)==0,"inline editing temporarily clears the non-activating desktop style so widgets accept keyboard input");Shell.EndInlineInput(w);check((Shell.ExtendedStyle(w)&0x08000000L)!=0,"finishing inline editing restores the non-activating desktop style");}finally{w.Close();}var calendar=new DesktopWidget(){Name="Calendar fixture",PluginId="calendar",Width=310,Height=350};var cal=new WidgetWindow(controller,calendar);try{cal.Show();cal.UpdateLayout();check(Texts(cal).Count(t=>Int32.TryParse(t.Text,out temporary))>=42,"calendar plugin renders six rows of date cells");check(Texts(cal).Any(t=>t.Text.Contains("农历")),"calendar plugin shows the lunar date and clock by default");}finally{cal.Close();}}
    static int temporary;
    static IEnumerable<TextBlock> Texts(DependencyObject root){var text=root as TextBlock;if(text!=null)yield return text;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Texts(VisualTreeHelper.GetChild(root,i)))yield return child;}
}
}
